; MIDI OUT, 31.25 kbaud 8N1; one MIDI byte per host mailbox word
; Generated by escgen from protocols/midi_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: MIDI 1.0 Detailed Specification 4.2, Hardware: 31.25 kbaud, 1 start, 8 data, 1 stop bit, LSB first
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ BIT, CLK_KHZ * 1000 // 31250
.default PIN_OUT, 0
.equ P_OUT, 1 << PIN_OUT

.own  PIN_OUT, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_OUT, P_OUT, P_OUT         ; idle levels
    ADDT  1
packet:
    POP   r0                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    EMIT  P_OUT, 0, P_OUT             ; start
    ADDT  BIT
    LDSH  r0                          ; 8 bits, LSB first
    LDLC  8
bit1:
    EMITX P_OUT, LSB, P_OUT           ; data bit
    ADDT  BIT
    DJNZ  bit1
    EMIT  P_OUT, P_OUT, P_OUT         ; stop
    ADDT  BIT
    JMP   packet
